package ca.yorku.eecs3311.coursepilot.cli; import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import org.springframework.stereotype.Component; import picocli.CommandLine.*;
@Component @Command(name="agent",description="Run a bounded multi-step course study task",mixinStandardHelpOptions=true) public class AgentCommand implements Runnable{private final StudyAgentFacade facade;public AgentCommand(StudyAgentFacade f){facade=f;}@Option(names="--course",required=true)String course;@Option(names="--request",required=true)String request;public void run(){var c=facade.getCourseByCode(course);System.out.println(facade.agentAssist(c.id(),request));}}
